CREATE TABLE projects(workspace_id TEXT REFERENCES workspaces(id), id TEXT, name TEXT NOT NULL, PRIMARY KEY(workspace_id,id));
CREATE TABLE releases(workspace_id TEXT, id TEXT, summary TEXT NOT NULL, deployed_at TEXT NOT NULL, PRIMARY KEY(workspace_id,id), FOREIGN KEY(workspace_id) REFERENCES workspaces(id));
CREATE TABLE runbooks(workspace_id TEXT, id TEXT, title TEXT NOT NULL, steps_json TEXT NOT NULL, PRIMARY KEY(workspace_id,id), FOREIGN KEY(workspace_id) REFERENCES workspaces(id));
CREATE TABLE issues(workspace_id TEXT, id TEXT, project_id TEXT NOT NULL, title TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('open','resolved')), severity TEXT NOT NULL, affected_users INTEGER NOT NULL, event_count INTEGER NOT NULL, release_id TEXT NOT NULL, runbook_id TEXT NOT NULL, owner_id TEXT REFERENCES users(id), last_seen TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(workspace_id,id), FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id), FOREIGN KEY(workspace_id,release_id) REFERENCES releases(workspace_id,id), FOREIGN KEY(workspace_id,runbook_id) REFERENCES runbooks(workspace_id,id));
CREATE INDEX issues_search ON issues(workspace_id,status,id);
CREATE TABLE event_samples(workspace_id TEXT, issue_id TEXT, id INTEGER, detail TEXT NOT NULL, PRIMARY KEY(workspace_id,issue_id,id), FOREIGN KEY(workspace_id,issue_id) REFERENCES issues(workspace_id,id));
